
const menu=document.querySelector('.mobile-menu');menu?.addEventListener('click',()=>{let open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('nav').classList.toggle('open',open)});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-category]').forEach(c=>c.classList.toggle('hidden',b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter))}));
function step(n){document.querySelectorAll('[data-step]').forEach(s=>s.classList.toggle('hidden',+s.dataset.step!==n));document.querySelectorAll('.progress span').forEach((s,i)=>s.classList.toggle('on',i<=n));document.querySelector(`[data-step="${n}"] h2`)?.setAttribute('tabindex','-1');document.querySelector(`[data-step="${n}"] h2`)?.focus()}
document.querySelectorAll('[data-next]').forEach(b=>b.addEventListener('click',()=>step(+b.dataset.next)));
let plan='';document.querySelector('#finish-plan')?.addEventListener('click',()=>{const val=id=>document.getElementById(id).value.trim();plan=`MY NEXT SMALL STEP\n\nAction: ${val('action')||val('situation')}\nWhen: ${val('when')||'A moment I choose this week'}\nMy prediction: ${val('prediction')||'I left this prompt blank.'}\nWhat I observed: ${val('evidence')||'I left this prompt blank.'}\nAnother possibility: ${val('alternative')||'I left this prompt blank.'}\n\nAfterwards: What happened? What surprised me? What did I learn?\n\nRespect the other person's response. One interaction is not a verdict on future connections.`;document.querySelectorAll('[data-step]').forEach(s=>s.classList.add('hidden'));document.querySelector('#plan-summary').textContent=plan;document.querySelector('#plan-summary').style.whiteSpace='pre-wrap';document.querySelector('#plan-result').classList.remove('hidden')});document.querySelector('#download-plan')?.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([plan],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='my-next-small-step.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
